package main

import "fmt"

// Animal is anything that can speak.
type Animal interface {
	Speak() string
}

// BaseAnimal is a plain animal with the default sound.
type BaseAnimal struct{}

func (BaseAnimal) Speak() string {
	return "..."
}

// Dog and Cat embed BaseAnimal, so they start with its Speak.
type Dog struct{ BaseAnimal }

type Cat struct{ BaseAnimal }

func (Dog) Speak() string {
	return "Woof"
}

func (Cat) Speak() string {
	return "Meow"
}

func makeAnimal(kind string) Animal {
	switch kind {
	case "dog":
		return Dog{}
	case "cat":
		return Cat{}
	default:
		return BaseAnimal{}
	}
}

func main() {
	var n int
	fmt.Scan(&n)
	for i := 0; i < n; i++ {
		var kind string
		fmt.Scan(&kind)
		animal := makeAnimal(kind)
		fmt.Println(animal.Speak())
	}
}

